INSERT INTO "documents" VALUES('interactions','stream:practice-2c81f478-de35-4349-bf9a-4238b9cadd08','{"id": "stream:practice-2c81f478-de35-4349-bf9a-4238b9cadd08", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$. Find $P(\\\\phi)$ and when it is zero.\", \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-98b421e583282044f7d0d4d3", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 3}');
INSERT INTO "documents" VALUES('practice_tasks','practice-2c81f478-de35-4349-bf9a-4238b9cadd08:0','{"id": "practice-2c81f478-de35-4349-bf9a-4238b9cadd08:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$. Find $P(\\phi)$ and when it is zero.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "$P(\\phi)$ is right; check when the cosine is $-1$.", "outcome": "needs_work", "evidence_id": "practice-evidence:practice-88b7932f-f865-4973-9d79-4c4daaec3393", "kind": "needs_work", "answer": "P = (1 + cos phi)/2, zero at phi = 0."}, {"action": "assess", "feedback": "Right: $P = (1 + \\cos\\phi)/2$, zero at $\\phi = \\pi$.", "outcome": "passed", "evidence_id": "practice-evidence:practice-928c06c4-e274-475b-9d58-81615adfc652", "kind": "hinted", "answer": "P = (1 + cos phi)/2, zero at phi = pi."}]}');
